using Godot;
using System;
using System.Linq;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class DestructionGizmoOperations:RefCounted
{
    private readonly ActorDataOperations _data=new();private readonly ActorAnimationOperations _animation=new();private readonly ModelMeshOperations _meshes=new();private readonly DestructionDefinitionOperations _definition=new();private readonly DestructionAuthoringOperations _authoring=new();
    private static Node Spatial(RefCounted owner)=>owner.Get("spatial").As<Node>();private static Node Editor(RefCounted owner)=>Spatial(owner).Get("editor").As<Node>();private static Control Gizmo(RefCounted owner)=>Spatial(owner).Get("gizmo").As<Control>();private static RefCounted Model(RefCounted owner)=>Editor(owner).Get("model").As<RefCounted>();private static RefCounted Physics(RefCounted owner)=>Editor(owner).Get("physics").As<RefCounted>();private static Node3D? Runtime(RefCounted owner)=>Spatial(owner).Call("primary").As<Node3D>();private static Resource Actor(Node runtime)=>runtime.Get("actor").As<Resource>();private static Camera3D Camera(RefCounted owner)=>Spatial(owner).Call("camera").As<Camera3D>();private static Vector2 Project(RefCounted owner,Vector3 point)=>Spatial(owner).Call("project",point).AsVector2();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;private static Settings Before(RefCounted owner)=>owner.Get("before").AsGodotDictionary();private Settings Operations(Resource actor)=>_data.get_value(actor,"destruction_operations",new Settings()).AsGodotDictionary();private static string Selected(Resource actor,Settings operations)=>actor.GetMeta("damage_selected_operation",operations.Count>0?operations.Keys.First():Variant.From("")).AsString();
    public bool available(RefCounted owner){var runtime=Runtime(owner);return runtime!=null&&_data.get_value(Actor(runtime),"destruction_enabled",false).AsBool()&&Operations(Actor(runtime)).Count>0;}
    public bool active(RefCounted owner)=>available(owner)&&Actor(Runtime(owner)!).GetMeta("damage_viewport_tool",false).AsBool();
    public Settings selected_operation(RefCounted owner){if(!available(owner))return new Settings();var actor=Actor(Runtime(owner)!);double time=actor.Get("animation_time").AsDouble();var operations=Get(_animation.sampled_values(actor,double.IsNaN(time)?0:time),"destruction_operations",new Settings()).AsGodotDictionary();return Get(operations,Selected(actor,operations),new Settings()).AsGodotDictionary();}
    public void draw(RefCounted owner){if(!available(owner))return;var gizmo=Gizmo(owner);var rect=Spatial(owner).Call("toolbar_rect",3).AsRect2();gizmo.DrawRect(rect,new Color(active(owner)?"285c57":"152430"));gizmo.DrawString(ThemeDB.FallbackFont,rect.Position+new Vector2(6,18),"Damage D",HorizontalAlignment.Left,66,11,new Color("ffd078"));if(!active(owner))return;var actor=Actor(Runtime(owner)!);if(actor.GetMeta("damage_pattern_preview",false).AsBool()&&!Editor(owner).Get("playing").AsBool())draw_pattern(owner);if(actor.GetMeta("damage_fragment_tool",false).AsBool()){draw_fragments(owner);return;}var operation=selected_operation(owner);if(operation.Count==0)return;var pose=Runtime(owner)!.Call("remote_transform").AsTransform3D();var point=pose*Get(operation,"position",Vector3.Zero).AsVector3();var lens=Camera(owner);if(lens.IsPositionBehind(point))return;var center=Project(owner,point);var edge=Project(owner,point+lens.GlobalBasis.X*(float)Math.Max(.001,Get(operation,"radius",.5).AsDouble()));gizmo.DrawArc(center,Math.Max(8,center.DistanceTo(edge)),0,Mathf.Tau,64,new Color("ffd078"),1.5f,true);gizmo.DrawCircle(center,7,new Color("ffd078"));gizmo.DrawCircle(center,3,new Color("152430"));gizmo.DrawString(ThemeDB.FallbackFont,new Vector2(12,58),"Drag damage center · Shift-wheel: radius · Ctrl: snap · Esc: exit",HorizontalAlignment.Left,-1,12,new Color("ffd078"));}
    public void draw_pattern(RefCounted owner){var actor=Actor(Runtime(owner)!);var controller=Physics(owner);var states=controller.Get("states").AsGodotDictionary();if(!states.TryGetValue(actor.Get("id"),out var state))return;var output=controller.Get("destruction").AsGodotObject().Call("prepare",controller,actor.Get("id"),state,actor.Get("values"),Operations(actor)).AsGodotDictionary();if(Get(output,"error","").AsString().Length>0)return;var pose=state.AsGodotDictionary()["pose"].AsTransform3D();int lines=0,interior=output["materials"].AsGodotArray().Count;var lens=Camera(owner);var gizmo=Gizmo(owner);foreach(var item in output["rows"].AsGodotArray()){var row=item.AsGodotDictionary();var mesh=row["mesh"].As<Resource>();var vertices=mesh.Get("vertices").AsVector3Array();var materials=mesh.Get("materials").AsInt32Array();var center=row["center"].AsVector3();foreach(var edge in _meshes.edges(mesh)){bool cap=edge["faces"].AsInt32Array().Any(face=>materials[face]==interior);if(!cap)continue;var a=pose*(vertices[edge["a"].AsInt32()]+center);var b=pose*(vertices[edge["b"].AsInt32()]+center);if(!lens.IsPositionBehind(a)&&!lens.IsPositionBehind(b))gizmo.DrawLine(Project(owner,a),Project(owner,b),new Color("ffcf70"),1.5f,true);if(++lines>4000)return;}}}
    private GArray Pieces(RefCounted owner,Resource actor){var states=Physics(owner).Get("display_states").AsGodotDictionary();return Get(Get(states,actor.Get("id").AsString(),new Settings()).AsGodotDictionary(),"destruction_fragments",new GArray()).AsGodotArray();}
    public void draw_fragments(RefCounted owner){var actor=Actor(Runtime(owner)!);var chosen=actor.GetMeta("damage_selected_fragments",new GArray()).AsGodotArray();var fragments=Pieces(owner,actor);var rules=_data.get_value(actor,"destruction_fragments",new Settings()).AsGodotDictionary();var lens=Camera(owner);var gizmo=Gizmo(owner);for(int i=0;i<fragments.Count;i++){var fragment=fragments[i].AsGodotDictionary();string key=_authoring.fragment_key(actor.Get("id").AsString(),fragment["id"].AsString());var point=fragment["pose"].AsTransform3D().Origin;if(lens.IsPositionBehind(point))continue;bool selected=chosen.Contains(key);var color=new Color(selected?"ffcf70":"78ddd1");var center=Project(owner,point);gizmo.DrawCircle(center,5,color);gizmo.DrawString(ThemeDB.FallbackFont,center+new Vector2(8,-5),(i+1).ToString(),HorizontalAlignment.Left,-1,12,color);if(selected){var target=Get(Get(rules,key,new Settings()).AsGodotDictionary(),"target",point).AsVector3();if(owner.Get("fragment_drag").AsBool())target=owner.Get("offset").AsVector3();if(!lens.IsPositionBehind(target)){var end=Project(owner,target);gizmo.DrawLine(center,end,color,1.5f,true);gizmo.DrawCircle(end,8,color,false,2,true);}}}gizmo.DrawString(ThemeDB.FallbackFont,new Vector2(12,58),"Pick pieces · Shift: group · Drag gold target: force guidance",HorizontalAlignment.Left,-1,12,new Color("ffd078"));}
    public void restore(RefCounted owner,Settings values,GArray animation){var actor=owner.Get("actor").As<Resource>();actor.Get("values").AsGodotDictionary()[new StringName("destruction_operations")]=_data.copy_value(values);actor.Get("animation_previews").AsGodotDictionary().Clear();Model(owner).Call("restore_animation",actor,animation);}
    public void cancel(RefCounted owner){if(Before(owner).Count>0){restore(owner,Before(owner),owner.Get("tracks").AsGodotArray());owner.Set("before",new Settings());}owner.Set("fragment_drag",false);}
    private static Vector3? PlaneHit(RefCounted owner,Settings ray)=>owner.Get("plane").AsPlane().IntersectsRay(ray["origin"].AsVector3(),ray["direction"].AsVector3());
}
